/**
 * IdentityColumnShim — PostgreSQL `GENERATED ... AS IDENTITY` compatibility shim for SQLite.
 *
 * PG syntax:
 *   id INT GENERATED BY DEFAULT AS IDENTITY
 *   id INT GENERATED ALWAYS AS IDENTITY
 *
 * Rewritten to SQLite:
 *   id INTEGER PRIMARY KEY AUTOINCREMENT
 *
 * Also rewrites PG `SERIAL` / `BIGSERIAL` / `SMALLSERIAL` pseudo-types:
 *   id SERIAL       → id INTEGER PRIMARY KEY AUTOINCREMENT (if no existing PK)
 *   id BIGSERIAL    → id INTEGER PRIMARY KEY AUTOINCREMENT (if no existing PK)
 *   id BIGSERIAL    → id INTEGER (if table already has a PRIMARY KEY)
 *
 * @module IdentityColumnShim
 */

import { protectSQL, restoreSQL } from './LiteralProtectionLayer';

const IDENTITY_PATTERN = /GENERATED\s+(?:BY\s+DEFAULT|ALWAYS)\s+AS\s+IDENTITY/i;

/**
 * Detect whether a SQL string contains a `GENERATED ... AS IDENTITY` clause.
 * Works on CREATE TABLE statements.
 *
 * @param sql - The SQL string to inspect.
 * @returns `true` if an identity column pattern is found.
 */
export function detectIdentityColumn(sql: string): boolean {
  // Detect only outside string literals/quoted identifiers/comments so a
  // mention inside `'GENERATED ALWAYS AS IDENTITY'` is not reported.
  return IDENTITY_PATTERN.test(protectSQL(sql).protectedSql);
}

/**
 * Rewrite a PostgreSQL `GENERATED ... AS IDENTITY` declaration into
 * SQLite-compatible `INTEGER PRIMARY KEY AUTOINCREMENT`.
 *
 * Handles:
 *   - `INT GENERATED BY DEFAULT AS IDENTITY` -> `INTEGER PRIMARY KEY AUTOINCREMENT`
 *   - `INT GENERATED ALWAYS AS IDENTITY` -> `INTEGER PRIMARY KEY AUTOINCREMENT`
 *   - `BIGINT|SMALLINT|INTEGER GENERATED ... AS IDENTITY` -> `INTEGER PRIMARY KEY AUTOINCREMENT`
 *   - With/without schema prefix on table names
 *   - With optional trailing `PRIMARY KEY` after identity declaration
 *
 * Only rewrites identity columns that appear inside a CREATE TABLE statement.
 *
 * @param sql - The SQL string to rewrite.
 * @returns The rewritten SQL string with identity column syntax replaced.
 */
export function rewriteIdentityColumn(sql: string): string {
  // Only operate on CREATE TABLE statements
  if (!/^\s*CREATE\s+TABLE\s/i.test(sql)) {
    return sql;
  }

  // Match a column definition with GENERATED ... AS IDENTITY
  // Pattern: column_name INT|BIGINT|SMALLINT|INTEGER [rest] GENERATED {BY DEFAULT|ALWAYS} AS IDENTITY
  // The rest can include NOT NULL, PRIMARY KEY, etc.
  // We replace the entire construct with: column_name INTEGER PRIMARY KEY AUTOINCREMENT
  const identityRegex = /(\b\w+\s+)(INT|BIGINT|SMALLINT|INTEGER)((?:\s+(?:NOT\s+)?NULL\s*|\s+PRIMARY\s+KEY\s*|\s+UNIQUE\s*)*?)(\s+GENERATED\s+(?:BY\s+DEFAULT|ALWAYS)\s+AS\s+IDENTITY)((?:\s+PRIMARY\s+KEY)?(?:\s+(?:NOT\s+)?NULL)?(?:\s+UNIQUE)?)/gi;

  const protectedSql = protectSQL(sql);

  const result = protectedSql.protectedSql.replace(
    identityRegex,
    (_match, colNamePart: string, _colType: string, _middle: string) => {
      // Replace with just `columnName INTEGER PRIMARY KEY AUTOINCREMENT`
      return `${colNamePart.trim()} INTEGER PRIMARY KEY AUTOINCREMENT`;
    },
  );

  return restoreSQL({ ...protectedSql, protectedSql: result });
}

/**
 * Detect whether a CREATE TABLE statement contains SERIAL / BIGSERIAL / SMALLSERIAL columns.
 *
 * @param sql - The SQL string to inspect.
 * @returns `true` if a serial column pattern is found.
 */
export function detectSerialColumn(sql: string): boolean {
  if (!/^\s*CREATE\s+TABLE\s/i.test(sql)) {
    return false;
  }
  // Detect only outside string literals so a `DEFAULT 'SERIAL'` column default
  // is not reported as a SERIAL pseudo-type.
  return /\b(SERIAL|BIGSERIAL|SMALLSERIAL)\b/i.test(protectSQL(sql).protectedSql);
}

/**
 * Rewrite PostgreSQL SERIAL / BIGSERIAL / SMALLSERIAL pseudo-types into
 * SQLite-compatible `INTEGER PRIMARY KEY AUTOINCREMENT`.
 *
 * Rules:
 * - First SERIAL-type column → `INTEGER PRIMARY KEY AUTOINCREMENT`
 * - Subsequent SERIAL-type columns → `INTEGER` (SQLite allows only one AUTOINCREMENT)
 * - If the table already has a PRIMARY KEY constraint → all SERIAL → `INTEGER`
 *
 * @param sql - The CREATE TABLE SQL to rewrite.
 * @returns The rewritten SQL string.
 */
export function rewriteSerialColumn(sql: string): string {
  if (!/^\s*CREATE\s+TABLE\s/i.test(sql)) {
    return sql;
  }

  // Protect literals so a `DEFAULT 'x SERIAL y'` string is never rewritten.
  const protectedSql = protectSQL(sql);

  // Does the DDL already have a PRIMARY KEY (inline or table-level)?
  const hasExistingPK = /\bPRIMARY\s+KEY\b/i.test(protectedSql.protectedSql);

  // Replace SERIAL/BIGSERIAL/SMALLSERIAL column types.
  // Regex matches: word_boundary column_name whitespace SERIAL-type word_boundary
  // Using a replacer function to track whether we've already auto-incremented.
  let autoIncrementAssigned = false;

  const serialRegex = /\b(\w+)\s+(SERIAL|BIGSERIAL|SMALLSERIAL)\b/gi;
  const result = protectedSql.protectedSql.replace(
    serialRegex,
    (_match: string, colName: string) => {
      if (autoIncrementAssigned || hasExistingPK) {
        return `${colName} INTEGER`;
      }
      autoIncrementAssigned = true;
      return `${colName} INTEGER PRIMARY KEY AUTOINCREMENT`;
    },
  );

  return restoreSQL({ ...protectedSql, protectedSql: result });
}
